declare(strict_types=1);
require_once __DIR__.'/tenant.php';
ob_start(static fn(string $html):string=>str_replace(
    ['GUI v8.26','padding:9px 12px;border:1px solid #bfc8d2','<a href="ai_settings.php">AI</a><a class="active" href="activity_log.php">','</nav>'],
    ['<a class="badge" href="version_log.php" title="Bekijk wijzigingen per versie">GUI V8.60</a>','padding:7px 10px;font-size:12px;line-height:1.2;border:1px solid #bfc8d2','<a href="ai_settings.php">AI</a><a href="backup_settings.php">Back-ups</a><a class="active" href="activity_log.php">','<a href="version_log.php">Versies</a></nav>'],
    $html
));
require_once __DIR__.'/activity.php';
$user=requireAdmin();
$error=''; $rows=[]; $q=trim((string)($_GET['q']??''));
try{
    $pdo=activityDb();
    $select='SELECT LogID,DatumTijd,Weergavenaam,Gebruikersnaam,Rol,Actie,Onderdeel,ObjectType,ObjectID,Omschrijving FROM ActiviteitenLog';
    if($q!==''){
        $like='%'.$q.'%';
        $sql=$select.' WHERE CONCAT_WS(\' \',Weergavenaam,Gebruikersnaam,Rol,Actie,Onderdeel,ObjectType,ObjectID,Omschrijving) LIKE ? ORDER BY LogID DESC LIMIT 500';
        $stmt=$pdo->prepare($sql); $stmt->execute([$like]); $rows=$stmt->fetchAll();
    }else $rows=$pdo->query($select.' ORDER BY LogID DESC LIMIT 500')->fetchAll();
}catch(Throwable $e){
    $error='Het activiteitenlogboek is nog niet beschikbaar. Voer eerst migrate_v8_04_activity_log.sql uit.';
}
function h(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
